INSERT INTO complaint (id, description, admin_response, auto_closed, closed_at, complaint_state, customer_id, complaint_type_id, responded_by, created_by, status_id) VALUES
('a1b2c3d4-0038-0001-0001-000000000001', 'El aire acondicionado del Spark GT no funcionaba durante todo el viaje',                            'Lamentamos el inconveniente. Se realizo revision tecnica y se aplico descuento del 15% en proxima reserva',  FALSE, '2024-11-10 09:00:00', 'RESOLVED', 'a1b2c3d4-0026-0001-0001-000000000002', 'a1b2c3d4-0037-0001-0001-000000000001', 'a1b2c3d4-0008-0001-0001-000000000006', 'a1b2c3d4-0008-0001-0001-000000000002', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000002', 'Me cobraron 45000 pesos adicionales sin justificacion en el extracto',                             'Se reviso el cobro y corresponde a exceso de kilometraje segun contrato firmado',                           FALSE, '2024-11-08 14:00:00', 'RESOLVED', 'a1b2c3d4-0026-0001-0001-000000000005', 'a1b2c3d4-0037-0001-0001-000000000002', 'a1b2c3d4-0008-0001-0001-000000000006', 'a1b2c3d4-0008-0001-0001-000000000005', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000003', 'El operador de la sede fue descortez al momento de recibir el vehiculo',                           NULL,                                                                                                       FALSE, NULL,                  'IN_REVIEW', 'a1b2c3d4-0026-0001-0001-000000000006', 'a1b2c3d4-0037-0001-0001-000000000003', NULL, 'a1b2c3d4-0008-0001-0001-000000000006', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000004', 'Habia una rayadura en la puerta trasera que no fue registrada en la inspeccion de entrega',        NULL,                                                                                                       FALSE, NULL,                  'PENDING',   'a1b2c3d4-0026-0001-0001-000000000010', 'a1b2c3d4-0037-0001-0001-000000000006', NULL, 'a1b2c3d4-0008-0001-0001-000000000010', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000005', 'Espere 2 horas para que me entregaran el vehiculo reservado con anticipacion',                     'Pedimos disculpas, hubo un retraso operativo. Se otorgo compensacion de un dia gratuito',                  FALSE, '2024-10-30 16:00:00', 'RESOLVED', 'a1b2c3d4-0026-0001-0001-000000000004', 'a1b2c3d4-0037-0001-0001-000000000005', 'a1b2c3d4-0008-0001-0001-000000000006', 'a1b2c3d4-0008-0001-0001-000000000004', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000006', 'El seguro no cubrio el rayonazo que tuve a pesar de tener cobertura total',                        NULL,                                                                                                       FALSE, NULL,                  'IN_REVIEW', 'a1b2c3d4-0026-0001-0001-000000000003', 'a1b2c3d4-0037-0001-0001-000000000007', NULL, 'a1b2c3d4-0008-0001-0001-000000000003', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000007', 'Calcularon mal el kilometraje extra, me cobraron 50km mas de los que hice',                        'Se reviso el GPS y el odometro, el cobro fue correcto segun los registros',                                FALSE, '2024-11-02 10:00:00', 'CLOSED',   'a1b2c3d4-0026-0001-0001-000000000009', 'a1b2c3d4-0037-0001-0001-000000000008', 'a1b2c3d4-0008-0001-0001-000000000006', 'a1b2c3d4-0008-0001-0001-000000000009', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000008', 'El contrato tenia clausulas que no fueron explicadas verbalmente al momento de la firma',           NULL,                                                                                                       FALSE, NULL,                  'PENDING',   'a1b2c3d4-0026-0001-0001-000000000001', 'a1b2c3d4-0037-0001-0001-000000000009', NULL, 'a1b2c3d4-0008-0001-0001-000000000001', 'a1b2c3d4-0001-0001-0001-000000000001'),
('a1b2c3d4-0038-0001-0001-000000000009', 'El vehiculo tenia olor a cigarrillo fuerte aunque en el reglamento dice que no se permite fumar',  'Se aplico servicio de desodorizacion y se informo al operador responsable de la ultima revision',         TRUE,  '2024-10-25 00:00:00', 'CLOSED',   'a1b2c3d4-0026-0001-0001-000000000008', 'a1b2c3d4-0037-0001-0001-000000000001', 'a1b2c3d4-0008-0001-0001-000000000006', 'a1b2c3d4-0008-0001-0001-000000000008', 'a1b2c3d4-0001-0001-0001-000000000001'),
